class Solution {
    struct TrieNode {
        TrieNode* children[26] = {};
        int count = 0;
    };

    TrieNode* root;

    void insert(const string& word) {
        TrieNode* node = root;
        for (char c : word) {
            int idx = c - 'a';
            if (!node->children[idx]) {
                node->children[idx] = new TrieNode();
            }
            node = node->children[idx];
            node->count++;
        }
    }

    int getScore(const string& word) {
        TrieNode* node = root;
        int score = 0;
        for (char c : word) {
            int idx = c - 'a';
            node = node->children[idx];
            score += node->count;
        }
        return score;
    }

public:
    vector<int> sumPrefixScores(vector<string>& words) {
        root = new TrieNode();
        for (const string& word : words) {
            insert(word);
        }
        vector<int> answer;
        answer.reserve(words.size());
        for (const string& word : words) {
            answer.push_back(getScore(word));
        }
        return answer;
    }
};
